-- Field validation and access matrix for the existing modules. No demo business records or users.

-- Existing Project pages show progress for all roles, scoped by project access.
update public.erp_module_definitions set readers=array['assistant_manager','site_supervisor','foreman','client','documents','budget','asset','hr','finance'] where key='progress';
update public.erp_module_definitions set readers=array_append(readers,'budget') where key in ('billing','payments');
update public.erp_module_definitions set readers=array_append(readers,'assistant_manager') where key='employees';
